265	    /**
266	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
267	     * source of truth for how an email is persisted, so inputs that differ only in letter case
268	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
269	     * (create and update, mapper or hand-copied) stores the same canonical value.
270	     *
271	     * @param email the raw email, possibly {@code null}
272	     * @return the lower-cased form, or {@code null} if the input was {@code null}
273	     */
274	    public static String normalizeEmail(String email) {
275	        return email == null ? null : email.toLowerCase();
276	    }
277	
278	    /**
279	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
280	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
281	     */
282	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
283	        "mailinator.com",
284	        "tempmail.com",
285	        "guerrillamail.com");
286	
287	    /**
288	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
289	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
290	     * This is the single source of truth for which email domains are rejected, shared by any
291	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
292	     *
293	     * @param email the owner's email, possibly {@code null}
294	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
295	     */
296	    public static boolean isDisposableEmailDomain(String email) {
297	        if (email == null) {
298	            return false;
299	        }
300	        int at = email.lastIndexOf('@');
301	        if (at < 0) {
302	            return false;
303	        }
304	        String domain = email.substring(at + 1).toLowerCase();
305	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
306	    }
307	
308	    /**
309	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
310	     * truth for how a telephone is compared and persisted, so inputs that differ only in
311	     * formatting (spaces, dashes, brackets) are treated as the same number.
312	     *
313	     * <p>The rules are:
314	     * <ul>
315	     *   <li>spaces, dashes and brackets are stripped;</li>
316	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
317	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
318	     *       is dropped from the national digits;</li>
319	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
320	     *   <li>for a recognized country code the national number (the digits after the country
321	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
322	     *       digits and {@code '+1'} requires 10.</li>
323	     * </ul>
324	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
325	     * values are returned unchanged.
326	     *
327	     * @param telephone the raw telephone, possibly {@code null}
328	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
329	     *     valid E.164 number
330	     */
331	    public static String normalizeTelephone(String telephone) {
332	        if (telephone == null) {
333	            return null;
334	        }
335	        String trimmed = telephone.trim();
336	        boolean hasCountryCode = trimmed.startsWith("+");
337	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
338	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
339	        if (hasCountryCode) {
340	            stripped = stripped.substring(1);
341	        }
342	        if (!stripped.matches("\\d+")) {
343	            return null;
344	        }
345	        String digits;
346	        if (hasCountryCode) {
347	            digits = stripped;
348	        } else {
349	            if (stripped.startsWith("0")) {
350	                stripped = stripped.substring(1);
351	            }
352	            digits = "61" + stripped;
353	        }
354	        if (digits.length() < 8 || digits.length() > 15) {
355	            return null;
356	        }
357	        if (!hasValidNationalNumberLength(digits)) {
358	            return null;
359	        }
360	        return "+" + digits;
361	    }
362	
363	    /**
364	     * Format a stored E.164 telephone for human display: the country code, a space, then the
365	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
366	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
367	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
368	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
369	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
370	     * kept unchanged elsewhere.
371	     *
372	     * @param telephone the stored E.164 telephone, possibly {@code null}
373	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
374	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
375	     *     unchanged
376	     */
377	    public static String telephoneDisplay(String telephone) {
378	        if (telephone == null) {
379	            return null;
380	        }
381	        if (!telephone.matches("\\+\\d+")) {
382	            return telephone;
383	        }
384	        String digits = telephone.substring(1);
385	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
386	            if (digits.startsWith(countryCode)) {
387	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
388	            }
389	        }
390	        return "+" + groupDigits(digits);
391	    }
392	
393	    /**
394	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
395	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
396	     * {@code "412345678"} becomes {@code "412 345 678"}).
397	     *
398	     * @param digits the national digits
399	     * @return the space-grouped digits
400	     */
401	    private static String groupDigits(String digits) {
402	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
403	        for (int i = 0; i < digits.length(); i++) {
404	            if (i > 0 && i % 3 == 0) {
405	                grouped.append(' ');
406	            }
407	            grouped.append(digits.charAt(i));
408	        }
409	        return grouped.toString();
410	    }
411	
412	    /**
413	     * Required national-number length (the count of digits after the country code) for each
414	     * recognized country code, longest country code first so the prefix match is unambiguous.
415	     */
416	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
417	    static {
418	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
419	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
420	    }
421	
422	    /**
423	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
424	     * length its country code requires. A country code with no registered length places no
425	     * additional constraint and is accepted.
426	     *
427	     * @param digits the E.164 digits without the leading {@code '+'}
428	     * @return {@code true} if the national-number length is valid for the country code
429	     */
430	    private static boolean hasValidNationalNumberLength(String digits) {
431	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
432	            String countryCode = entry.getKey();
433	            if (digits.startsWith(countryCode)) {
434	                return digits.length() - countryCode.length() == entry.getValue();
435	            }
436	        }
437	        return true;
438	    }
439	
440	    /**
441	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
442	     * upper-cased abbreviation.
443	     */
444	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
445	        "ST", "STREET",
446	        "RD", "ROAD",
447	        "AVE", "AVENUE");
448	
449	    /**
450	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
451	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
452	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
453	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
454	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
455	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
456	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
457	     * value. The transform is idempotent: a normalized address normalizes to itself.
458	     *
459	     * @param address the raw address, possibly {@code null}
460	     * @return the normalized form, or {@code null} if the input was {@code null}
461	     */
462	    public static String normalizeAddress(String address) {
463	        if (address == null) {
464	            return null;
465	        }
466	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
467	        if (collapsed.isEmpty()) {
468	            return collapsed;
469	        }
470	        String[] tokens = collapsed.split(" ");
471	        StringBuilder normalized = new StringBuilder(collapsed.length());
472	        for (int i = 0; i < tokens.length; i++) {
473	            if (i > 0) {
474	                normalized.append(' ');
475	            }
476	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
477	        }
478	        return normalized.toString();
479	    }
480	
481	    /**
482	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
483	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
484	     * result is that line, with a single space and {@code addressLine2} appended when the second line
485	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
486	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
487	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
488	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
489	     *
490	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
491	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
492	     * @param flatAddress the normalized flat address, possibly {@code null}
493	     * @return the composed address, or the flat value / {@code null} when no structured line is present
494	     */
495	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
496	        if (isPresent(addressLine1)) {
497	            if (isPresent(addressLine2)) {
498	                return addressLine1 + " " + addressLine2;
499	            }
500	            return addressLine1;
501	        }
502	        return flatAddress;
503	    }
504	
505	    /**
506	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
507	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
508	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
509	     *
510	     * @param value the address field, possibly {@code null}
511	     * @return {@code true} if the value is present and non-blank
512	     */
513	    private static boolean isPresent(String value) {
514	        return value != null && !value.isBlank();
515	    }
516	
517	    /**
518	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
519	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
520	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
521	     *
522	     * @param addressLine1 the structured first line, possibly {@code null}
523	     * @param address the flat address, possibly {@code null}
524	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
525	     */
526	    public static boolean hasAddress(String addressLine1, String address) {
527	        return isPresent(addressLine1) || isPresent(address);
528	    }
529	
530	    /**
531	     * Normalize a household field (such as last name or address) to its canonical form for
532	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
533	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
534	     * that differ only in letter case or spacing are treated as the same value.
535	     *
536	     * @param value the raw field value, possibly {@code null}
537	     * @return the normalized form, or {@code null} if the input was {@code null}
538	     */
539	    public static String normalizeHousehold(String value) {
540	        if (value == null) {
541	            return null;
542	        }
543	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
544	    }
545	
546	    /**
547	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
548	     * last name (compared case-insensitively with collapsed whitespace, see
549	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
550	     * those two fields, so two owners who share a last name and postcode are assigned the same id
551	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
552	     * upper-cased hex characters of the SHA-256 digest of
553	     * {@code normalizedLastName + '|' + postcode}.
554	     *
555	     * @param lastName the owner's last name, possibly {@code null}
556	     * @param postcode the owner's postcode, possibly {@code null}
557	     * @return the household id, or {@code null} if either field is {@code null}
558	     */
559	    public static String householdId(String lastName, String postcode) {
560	        String normalizedLastName = normalizeHousehold(lastName);
561	        if (normalizedLastName == null || postcode == null) {
562	            return null;
563	        }
564	        String key = normalizedLastName + "|" + postcode;
565	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
566	    }
567	
568	    /**
569	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
570	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
571	     * so they all agree on algorithm and encoding.
572	     *
573	     * @param value the string to digest, never {@code null}
574	     * @return the 64-character lower-case hex digest
575	     */
576	    private static String sha256Hex(String value) {
577	        try {
578	            byte[] digest = MessageDigest.getInstance("SHA-256")
579	                .digest(value.getBytes(StandardCharsets.UTF_8));
580	            StringBuilder hex = new StringBuilder(digest.length * 2);
581	            for (byte b : digest) {
582	                hex.append(String.format("%02x", b));
583	            }
584	            return hex.toString();
585	        } catch (NoSuchAlgorithmException e) {
586	            // SHA-256 is a standard algorithm required to be present on every JVM.
587	            throw new IllegalStateException("SHA-256 not available", e);
588	        }
589	    }
590	
591	    /**
592	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
593	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
594	     * <ul>
595	     *   <li>{@code REGION} is the region code derived from the postcode (see
596	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
597	     *       in no known range, and</li>
598	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
599	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
600	     *       name.</li>
601	     * </ul>
602	     * The value is deterministic in the postcode, telephone and last name (e.g.
603	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
604	     *
605	     * @param postcode the owner's postcode, possibly {@code null}
606	     * @param telephone the owner's raw telephone, possibly {@code null}
607	     * @param lastName the owner's last name, possibly {@code null}
608	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
609	     */
610	    public static String customerCode(String postcode, String telephone, String lastName) {
611	        if (telephone == null || lastName == null) {
612	            return null;
613	        }
614	        String region = regionForPostcode(postcode);
615	        if (region == null) {
616	            region = "UNKNOWN";
617	        }
618	        String normalizedTelephone = normalizeTelephone(telephone);
619	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
620	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
621	    }
622	
623	    /**
624	     * Compute an owner's {@code identityKey}, the single derived value through which all
625	     * duplicate detection is now expressed. It consolidates the three formerly separate
626	     * telephone, email and household duplicate checks into one key, formatted as
627	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
628	     * <ul>
629	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
630	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
631	     *       when no email is present, and</li>
632	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
633	     * </ul>
634	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
635	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
636	     * members of the same household with different telephones have different keys.
637	     *
638	     * @param telephone the owner's raw telephone, possibly {@code null}
639	     * @param email the owner's email, possibly {@code null}
640	     * @param lastName the owner's last name, possibly {@code null}
641	     * @param postcode the owner's postcode, possibly {@code null}
642	     * @return the identity key, never {@code null}
643	     */
644	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
645	        String normalizedTelephone = normalizeTelephone(telephone);
646	        String normalizedEmail = normalizeEmail(email);
647	        String household = householdId(lastName, postcode);
648	        return (normalizedTelephone == null ? "" : normalizedTelephone)
649	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
650	            + "|" + (household == null ? "" : household);
651	    }
652	
653	    /**
654	     * The month in which the fiscal year starts (1 July). Dates on or after this month belong to
655	     * the fiscal year named for the following calendar year.
656	     */
657	    private static final int FISCAL_YEAR_START_MONTH = 7;
658	
659	    /**
660	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
661	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
662	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
663	     * year of its own calendar year.
664	     *
665	     * @param date the date to resolve, never {@code null}
666	     * @return the fiscal-year number (a four-digit calendar year)
667	     */
668	    private static int fiscalYearNumber(LocalDate date) {
669	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
670	    }
671	
672	    /**
673	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
674	     * where {@code YY} is the last two digits of the fiscal-year number (see
675	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
676	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
677	     *
678	     * @param date the date to derive the fiscal year from, possibly {@code null}
679	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
680	     */
681	    public static String fiscalYear(LocalDate date) {
682	        if (date == null) {
683	            return null;
684	        }
685	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
686	    }
687	
688	    /**
689	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
690	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
691	     * is the last two digits of the registration date's fiscal year (see
692	     * {@link #fiscalYear(LocalDate)}), e.g. {@code 'NSW-1A2B3C4D-M27'}. The value is deterministic
693	     * in those two fields.
694	     *
695	     * @param customerCode the owner's customer code, possibly {@code null}
696	     * @param registrationDate the owner's registration date, possibly {@code null}
697	     * @return the membership number, or {@code null} if either field is {@code null}
698	     */
699	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
700	        if (customerCode == null || registrationDate == null) {
701	            return null;
702	        }
703	        return String.format("%s-M%02d", customerCode, fiscalYearNumber(registrationDate) % 100);
704	    }
705	
706	    /**
707	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
708	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
709	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
710	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
711	     * of elapsed fiscal years from {@code registrationDate} to today, see
712	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
713	     * points accrue only once the owner has been a member for more than a full fiscal year.
714	     *
715	     * @param namesakeCount the owner's namesake count, possibly {@code null}
716	     * @param email the owner's email, possibly {@code null}
717	     * @param householdCount the number of members in the owner's household, possibly {@code null}
718	     * @param registrationDate the owner's registration date, possibly {@code null}
719	     * @return the membership points, a non-negative integer
720	     */
721	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
722	            LocalDate registrationDate) {
723	        int points = 0;
724	        if (email != null && !email.isEmpty()) {
725	            points += 2;
726	        }
727	        if (namesakeCount != null && namesakeCount == 0) {
728	            points += 1;
729	        }
730	        if (householdCount != null && householdCount >= 3) {
731	            points += 2;
732	        }
733	        if (registrationDate != null
734	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
735	            points += 3;
736	        }
737	        return points;
738	    }
739	
740	    /**
741	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
742	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
743	     *
744	     * @param membershipPoints the owner's membership points
745	     * @return the membership level, an integer from 1 to 4
746	     */
747	    public static int membershipLevel(int membershipPoints) {
748	        if (membershipPoints >= 6) {
749	            return 4;
750	        }
751	        if (membershipPoints >= 4) {
752	            return 3;
753	        }
754	        if (membershipPoints >= 2) {
755	            return 2;
756	        }
757	        return 1;
758	    }
759	
760	    /**
761	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
762	     * for postcode validation, keyed by the exact city name.
763	     */
764	    private static final Map<String, String> CITY_REGION = Map.of(
765	        "Sydney", "NSW",
766	        "Melbourne", "VIC",
767	        "Brisbane", "QLD");
768	
769	    /**
770	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
771	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
772	     * Because the customer code's region is itself derived from the postcode, the locality now shares
773	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
774	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
775	     *
776	     * @param customerCode the owner's customer code, possibly {@code null}
777	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
778	     */
779	    public static String locality(String customerCode) {
780	        if (customerCode == null) {
781	            return "UNKNOWN";
782	        }
783	        int dash = customerCode.indexOf('-');
784	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
785	    }
786	
787	    /**
788	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
789	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
790	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
791	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
792	     */
793	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
794	        "NSW", "Australia/Sydney",
795	        "VIC", "Australia/Melbourne",
796	        "QLD", "Australia/Brisbane");
797	
798	    /**
799	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
800	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
801	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
802	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
803	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
804	     * timezone and yields {@code null}.
805	     *
806	     * @param customerCode the owner's customer code, possibly {@code null}
807	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
808	     */
809	    public static String timezone(String customerCode) {
810	        return REGION_TIMEZONE.get(locality(customerCode));
811	    }
812	
813	    /**
814	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
815	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
816	     *
817	     * @param city the owner's city, possibly {@code null}
818	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
819	     */
820	    private static String regionForCity(String city) {
821	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
822	    }
823	
824	    /**
825	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
826	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
827	     * inclusive low and high bound of the region's valid 4-digit postcodes
828	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
829	     * table (including {@code 'UNKNOWN'}) places no range constraint.
830	     */
831	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
832	        "NSW", new int[] {2000, 2099},
833	        "VIC", new int[] {3000, 3099},
834	        "QLD", new int[] {4000, 4099});
835	
836	    /**
837	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
838	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
839	     * digits, or one that falls in no known range resolves to {@code null}.
840	     *
841	     * @param postcode the owner's postcode, possibly {@code null}
842	     * @return the matching region, or {@code null} when no range contains the postcode
843	     */
844	    private static String regionForPostcode(String postcode) {
845	        if (postcode == null || !postcode.matches("\\d{4}")) {
846	            return null;
847	        }
848	        int value = Integer.parseInt(postcode);
849	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
850	            int[] range = entry.getValue();
851	            if (value >= range[0] && value <= range[1]) {
852	                return entry.getKey();
853	            }
854	        }
855	        return null;
856	    }
857	
858	    /**
859	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
860	     * {@code null} or empty postcode is always valid. When present it must be exactly four
861	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
862	     * range the value must fall within that inclusive range. A city with no known region accepts
863	     * any four-digit postcode. This is the single source of
864	     * truth for postcode validity, shared by the DTO validation and any persistence path.
865	     *
866	     * @param postcode the owner's postcode, possibly {@code null}
867	     * @param city the owner's city, possibly {@code null}
868	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
869	     */
870	    public static boolean isPostcodeValidForCity(String postcode, String city) {
871	        if (postcode == null || postcode.isEmpty()) {
872	            return true;
873	        }
874	        if (!postcode.matches("\\d{4}")) {
875	            return false;
876	        }
877	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
878	        if (range == null) {
879	            return true;
880	        }
881	        int value = Integer.parseInt(postcode);
882	        return value >= range[0] && value <= range[1];
883	    }
884	
885	    /**
886	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
887	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
888	     * value is deterministic in the customer code and is the standard Luhn check digit: each
889	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
890	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
891	     * brings the weighted sum up to the next multiple of ten.
892	     *
893	     * @param customerCode the owner's customer code, possibly {@code null}
894	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
895	     */
896	    public static Integer checkDigit(String customerCode) {
897	        if (customerCode == null) {
898	            return null;
899	        }
900	        int sum = 0;
901	        boolean dbl = true;
902	        for (int i = customerCode.length() - 1; i >= 0; i--) {
903	            char c = customerCode.charAt(i);
904	            if (c < '0' || c > '9') {
905	                continue;
906	            }
907	            int d = c - '0';
908	            if (dbl) {
909	                d *= 2;
910	                if (d > 9) {
911	                    d -= 9;
912	                }
913	            }
914	            sum += d;
915	            dbl = !dbl;
916	        }
917	        return (10 - (sum % 10)) % 10;
918	    }
919	
920	    /**
921	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
922	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
923	     * is deterministic in the email.
924	     *
925	     * @param email the owner's email, possibly {@code null}
926	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
927	     */
928	    public static String contactPreference(String email) {
929	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
930	    }
931	
932	    /**
933	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
934	     * When a title is present the result is the title and the last name separated by a single space
935	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
936	     * value is deterministic in those two fields.
937	     *
938	     * @param title the owner's honorific title, possibly {@code null} or blank
939	     * @param lastName the owner's last name, possibly {@code null}
940	     * @return the composed salutation
941	     */
942	    public static String salutation(String title, String lastName) {
943	        if (title == null || title.isBlank()) {
944	            return lastName;
945	        }
946	        return title + " " + lastName;
947	    }
948	
949	    /**
950	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
951	     * date. The age in whole years is the number of completed years between {@code birthDate} and
952	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
953	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
954	     * two fields and is only defined when both are present.
955	     *
956	     * @param birthDate the owner's date of birth, possibly {@code null}
957	     * @param registrationDate the owner's registration date, possibly {@code null}
958	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
959	     *     is {@code null}
960	     */
961	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
962	        if (birthDate == null || registrationDate == null) {
963	            return null;
964	        }
965	        int age = Period.between(birthDate, registrationDate).getYears();
966	        if (age < 18) {
967	            return "MINOR";
968	        }
969	        if (age < 65) {
970	            return "ADULT";
971	        }
972	        return "SENIOR";
973	    }
974	
975	    protected Set<Pet> getPetsInternal() {
976	        if (this.pets == null) {
977	            this.pets = new HashSet<>();
978	        }
979	        return this.pets;
980	    }
981	
982	    protected void setPetsInternal(Set<Pet> pets) {
983	        this.pets = pets;
984	    }
985	
986	    public List<Pet> getPets() {
987	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
988	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
989	        return Collections.unmodifiableList(sortedPets);
990	    }
991	
992	    public void setPets(List<Pet> pets) {
993	        this.pets = new HashSet<>(pets);
994	    }
995	
996	    public void addPet(Pet pet) {
997	        getPetsInternal().add(pet);
998	        pet.setOwner(this);
999	    }
1000	
1001	    /**
1002	     * Return the Pet with the given name, or null if none found for this Owner.
1003	     *
1004	     * @param name to test
1005	     * @return true if pet name is already in use
1006	     */
1007	    public Pet getPet(String name) {
1008	        return getPet(name, false);
1009	    }
1010	
1011	    /**
1012	     * Return the Pet with the given name, or null if none found for this Owner.
1013	     *
1014	     * @param name to test
1015	     * @return true if pet name is already in use
1016	     */
1017	    public Pet getPet(String name, boolean ignoreNew) {
1018	        name = name.toLowerCase();
1019	        for (Pet pet : getPetsInternal()) {
1020	            if (!ignoreNew || !pet.isNew()) {
1021	                String compName = pet.getName();
1022	                compName = compName.toLowerCase();
1023	                if (compName.equals(name)) {
1024	                    return pet;
1025	                }
1026	            }
1027	        }
1028	        return null;
1029	    }
1030	
1031	    public Pet getPet(Integer petId) {
1032	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
1033	    }
1034	
1035	    @Override
1036	    public String toString() {
1037	        return new ToStringCreator(this)
1038	
1039	            .append("id", this.getId())
1040	            .append("new", this.isNew())
1041	            .append("lastName", this.getLastName())
1042	            .append("firstName", this.getFirstName())
1043	            .append("address", this.address)
1044	            .append("city", this.city)
1045	            .append("telephone", this.telephone)
1046	            .toString();
1047	    }
1048	}
