277	    /**
278	     * Save an owner, enforcing the create-time business rules.
279	     *
280	     * <p>Because the household is keyed on {@code (lastName, postcode)} (see
281	     * {@link Owner#householdId(String, String)}), owners sharing a last name and postcode are the
282	     * same household. On create, a second owner in an existing household is rejected as a household
283	     * duplicate (see {@link #assertHouseholdIsUnique(Owner)}) <em>unless</em> {@code sharesHousehold}
284	     * is set, in which case it is accepted as a declared household member. The {@code sharesHousehold}
285	     * flag therefore only bypasses that duplicate block; a declared member is also not flagged as a
286	     * possible (suspected) duplicate.
287	     */
288	    @Override
289	    @Transactional
290	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
291	        boolean isCreate = owner.isNew();
292	        assertEmailDomainAllowed(owner);
293	        assertIdentityIsUnique(owner);
294	        if (owner.isNew()) {
295	            assertCityHasCapacity(owner);
296	            if (!sharesHousehold) {
297	                assertHouseholdIsUnique(owner);
298	            }
299	        }
300	        if (owner.getRegistrationDate() == null) {
301	            owner.setRegistrationDate(LocalDate.now());
302	        }
303	        assertRegistrationDateNotInFuture(owner);
304	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
305	        if (owner.isNew()) {
306	            assertDailyRegistrationLimit(owner);
307	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
308	        }
309	        if (owner.isNew() && owner.getCustomerCode() == null) {
310	            owner.setCustomerCode(generateCustomerCode(owner));
311	        }
312	        if (owner.isNew() && owner.getNamesakeCount() == null) {
313	            owner.setNamesakeCount(countNamesakes(owner));
314	        }
315	        if (owner.isNew() && owner.getHouseholdCount() == null) {
316	            owner.setHouseholdCount(countHouseholdMembers(owner));
317	        }
318	        if (owner.isNew()) {
319	            assignPossibleDuplicate(owner, sharesHousehold);
320	        }
321	        ownerRepository.save(owner);
322	        if (isCreate) {
323	            String membershipNumber = Owner.membershipNumber(owner.getCustomerCode(),
324	                owner.getRegistrationDate());
325	            int membershipLevel = Owner.membershipLevel(Owner.membershipPoints(
326	                owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdCount(),
327	                owner.getRegistrationDate()));
328	            AUDIT.info("owner created id={} customerCode={} registrationDate={} "
329	                    + "membershipLevel={} membershipNumber={}",
330	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
331	                membershipLevel, membershipNumber);
332	        }
333	    }
334	
335	    /**
336	     * Count the existing owners that, at the moment this owner is created, share its first name
337	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
338	     * it never counts itself. This value is deterministic given the current data, so it is computed
339	     * once at creation time and stored.
340	     */
341	    private Integer countNamesakes(Owner owner) {
342	        String firstName = owner.getFirstName();
343	        String lastName = owner.getLastName();
344	        if (firstName == null || lastName == null) {
345	            return 0;
346	        }
347	        return (int) ownerRepository.findAll().stream()
348	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
349	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
350	                && lastName.equalsIgnoreCase(existing.getLastName()))
351	            .count();
352	    }
353	
354	    /**
355	     * Count the members of this owner's household at the moment it is created, i.e. the number of
356	     * owners sharing its household id (same last name and postcode, see
357	     * {@link Owner#householdId(String, String)}) plus this owner itself. An owner with no derivable
358	     * household id (missing last name or postcode) is counted as a single-member household. The value
359	     * is deterministic given the current data, so it is computed once at creation time and stored.
360	     */
361	    private Integer countHouseholdMembers(Owner owner) {
362	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
363	        if (householdId == null) {
364	            return 1;
365	        }
366	        long others = ownerRepository.findAll().stream()
367	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
368	            .filter(existing -> householdId.equals(
369	                Owner.householdId(existing.getLastName(), existing.getPostcode())))
370	            .count();
371	        return (int) others + 1;
372	    }
373	
374	    /**
375	     * Build an owner's {@code customerCode} formatted {@code '<REGION>-<HASH8>'}, where {@code REGION}
376	     * is the region code derived from the owner's postcode (or {@code 'UNKNOWN'} when no region can be
377	     * derived) and {@code HASH8} is the first eight upper-cased hex characters of SHA-256 over the
378	     * owner's normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The
379	     * base value is deterministic in those fields and carries no sequence number (see
380	     * {@link Owner#customerCode(String, String, String)}).
381	     *
382	     * <p>When that computed code collides with an existing owner's {@code customerCode}, this appends
383	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it unique (e.g. a second owner
384	     * computing {@code 'NSW-1A2B3C4D'} is stored as {@code 'NSW-1A2B3C4D-2'}), so distinct owners always
385	     * receive distinct customer codes. A {@code null} computed code (missing telephone or last name) is
386	     * returned unchanged.
387	     */
388	    private String generateCustomerCode(Owner owner) {
389	        String base = Owner.customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName());
390	        if (base == null) {
391	            return null;
392	        }
393	        Set<String> existing = ownerRepository.findAll().stream()
394	            .filter(other -> !Objects.equals(other.getId(), owner.getId()))
395	            .map(Owner::getCustomerCode)
396	            .filter(Objects::nonNull)
397	            .collect(Collectors.toSet());
398	        if (!existing.contains(base)) {
399	            return base;
400	        }
401	        int n = 2;
402	        while (existing.contains(base + "-" + n)) {
403	            n++;
404	        }
405	        return base + "-" + n;
406	    }
407	
408	    /**
409	     * Flag a newly created owner as a possible (soft) duplicate of an existing owner. A hard
410	     * duplicate (an owner reusing an existing normalized telephone) has already been rejected by
411	     * {@link #assertIdentityIsUnique(Owner)}, and an undeclared household duplicate by
412	     * {@link #assertHouseholdIsUnique(Owner)}, before this runs. This detects the weaker overlap: an
413	     * existing owner that shares this owner's household id (same last name and postcode, see
414	     * {@link Owner#householdId(String, String)}) but has a <em>different</em> normalized telephone.
415	     * When such an owner exists, {@code possibleDuplicate} is set {@code true} and
416	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match);
417	     * otherwise {@code possibleDuplicate} is set {@code false} and {@code possibleDuplicateOf} left unset.
418	     *
419	     * <p>A declared household member ({@code sharesHousehold} set) is never a suspected duplicate: it
420	     * deliberately joins an existing household, so it is left unflagged.
421	     */
422	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
423	        if (sharesHousehold) {
424	            owner.setPossibleDuplicate(false);
425	            owner.setPossibleDuplicateOf(null);
426	            return;
427	        }
428	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
429	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
430	        Integer match = null;
431	        if (householdId != null) {
432	            match = ownerRepository.findAll().stream()
433	                .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
434	                .filter(existing -> !existing.isDeleted())
435	                .filter(existing -> householdId.equals(
436	                    Owner.householdId(existing.getLastName(), existing.getPostcode())))
437	                .filter(existing -> !Objects.equals(normalizedTelephone,
438	                    Owner.normalizeTelephone(existing.getTelephone())))
439	                .map(Owner::getId)
440	                .filter(Objects::nonNull)
441	                .min(Integer::compareTo)
442	                .orElse(null);
443	        }
444	        owner.setPossibleDuplicate(match != null);
445	        owner.setPossibleDuplicateOf(match);
446	    }
447	
448	    /**
449	     * Enforce that the owner's email domain is not on the disposable-domain blocklist, throwing
450	     * {@link DisposableEmailDomainException} when it is. The blocklist check is the single source
451	     * of truth in {@link Owner#isDisposableEmailDomain(String)}; an owner with no email places no
452	     * constraint.
453	     */
454	    private void assertEmailDomainAllowed(Owner owner) {
455	        if (Owner.isDisposableEmailDomain(owner.getEmail())) {
456	            throw new DisposableEmailDomainException(owner.getEmail());
457	        }
458	    }
459	
460	    /**
461	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
462	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
463	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
464	     * (normalized telephone, normalized email (or empty) and household id, see
465	     * {@link Owner#identityKey(String, String, String, String)}).
466	     *
467	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
468	     * key when their normalized telephones already match; the normalized telephone is therefore the
469	     * decisive component and is what this check compares. Consequently two members of the same
470	     * household with different telephones have different identity keys and are both allowed, while
471	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
472	     * excluded by id so updating an owner in place never conflicts with itself.
473	     */
474	    private void assertIdentityIsUnique(Owner owner) {
475	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
476	        if (normalizedTelephone == null) {
477	            return;
478	        }
479	        boolean duplicate = ownerRepository.findAll().stream()
480	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
481	            .filter(existing -> !existing.isDeleted())
482	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
483	            .anyMatch(normalizedTelephone::equals);
484	        if (duplicate) {
485	            throw new DuplicateIdentityException(Owner.identityKey(
486	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
487	        }
488	    }
489	
490	    /**
491	     * Enforce that no <em>other</em> owner already belongs to this owner's household, throwing
492	     * {@link DuplicateIdentityException} if one does. The household is keyed on {@code (lastName,
493	     * postcode)} (see {@link Owner#householdId(String, String)}), so owners sharing a last name and
494	     * postcode are the same household and a second such owner is a household duplicate. The owner
495	     * being saved is excluded by id, and an owner with no derivable household id (missing last name
496	     * or postcode) places no constraint. Callers bypass this check for a declared household member
497	     * ({@code sharesHousehold} set).
498	     */
499	    private void assertHouseholdIsUnique(Owner owner) {
500	        String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
501	        if (householdId == null) {
502	            return;
503	        }
504	        boolean duplicate = ownerRepository.findAll().stream()
505	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
506	            .filter(existing -> !existing.isDeleted())
507	            .map(existing -> Owner.householdId(existing.getLastName(), existing.getPostcode()))
508	            .anyMatch(householdId::equals);
509	        if (duplicate) {
510	            throw new DuplicateIdentityException(Owner.identityKey(
511	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode()));
512	        }
513	    }
514	
515	    /**
516	     * Enforce that the owner's city has not yet reached its capacity, throwing
517	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
518	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
519	     */
520	    private void assertCityHasCapacity(Owner owner) {
521	        String city = owner.getCity();
522	        if (city == null) {
523	            return;
524	        }
525	        long count = ownerRepository.findAll().stream()
526	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
527	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
528	            .count();
529	        if (count >= MAX_OWNERS_PER_CITY) {
530	            throw new CityAtCapacityException(city);
531	        }
532	    }
533	
534	    /**
535	     * Enforce that the owner's registration date is not later than the current server date, throwing
536	     * {@link FutureRegistrationDateException} when it is. A registration date may not be in the
537	     * future; a date defaulted to {@link LocalDate#now()} is never in the future, so this check is a
538	     * harmless no-op for that case.
539	     */
540	    private void assertRegistrationDateNotInFuture(Owner owner) {
541	        LocalDate registrationDate = owner.getRegistrationDate();
542	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
543	            throw new FutureRegistrationDateException(registrationDate);
544	        }
545	    }
546	
547	    /**
548	     * Roll a registration date forward to the next business day. A date that falls on a Saturday,
549	     * Sunday or a listed public holiday is advanced to the following non-holiday weekday; a plain
550	     * weekday is returned unchanged. This is applied to the effective registration date (whether
551	     * supplied in the request or defaulted to the server date) so that every value derived from
552	     * it&mdash;such as the membership number's year segment and the daily create-limit
553	     * counting&mdash;uses the adjusted business day.
554	     */
555	    private static LocalDate rollToBusinessDay(LocalDate date) {
556	        if (date == null) {
557	            return null;
558	        }
559	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
560	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
561	                || PUBLIC_HOLIDAYS.contains(date)) {
562	            date = date.plusDays(1);
563	        }
564	        return date;
565	    }
566	
567	    /**
568	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
569	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
570	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
571	     * is excluded by id.
572	     */
573	    private void assertDailyRegistrationLimit(Owner owner) {
574	        LocalDate registrationDate = owner.getRegistrationDate();
575	        if (registrationDate == null) {
576	            return;
577	        }
578	        long count = ownerRepository.findAll().stream()
579	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
580	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
581	            .count();
582	        if (count >= MAX_OWNERS_PER_DAY) {
583	            throw new DailyRegistrationLimitException(registrationDate);
584	        }
585	    }
586	
587	    /**
588	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
589	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
590	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
591	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
592	     * stored on the owner.
593	     */
594	    private boolean computeBulkSignupWarning(Owner owner) {
595	        LocalDate registrationDate = owner.getRegistrationDate();
596	        if (registrationDate == null) {
597	            return false;
598	        }
599	        long count = ownerRepository.findAll().stream()
600	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
601	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
602	            .count();
603	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
604	    }
605	
606	    @Override
607	    @Transactional(readOnly = true)
608	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
609	        return ownerRepository.findByLastName(lastName);
610	    }
611	
612	    @Override
613	    @Transactional(readOnly = true)
614	    public Collection<Visit> findVisitsByPetId(int petId) {
615	        return visitRepository.findByPetId(petId);
616	    }
617	
618	    @Override
619	    @Transactional(readOnly = true)
620	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
621	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
622	    }
623	
624	    private <T> T findEntityById(Supplier<T> supplier) {
625	        try {
626	            return supplier.get();
627	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
628	            // Just ignore not found exceptions for Jdbc/Jpa realization
629	            return null;
630	        }
631	    }
632	
633	}
